	PROFILE_UpdateParam(Profile, PROFILE_TABLE_8, ProfileADM10PerfLnODU2EBIdx[Idx], &LnODU2Perf[Idx].EB, State);
	PROFILE_UpdateParam(Profile, PROFILE_TABLE_8, ProfileADM10PerfLnODU2ESIdx[Idx], &LnODU2Perf[Idx].ES, State);
