static void PROFILE_ADM10_LINE_UpdatePerfValues(PROFILE_T *Profile, uint32_t Idx)
{
	uint32_t i;
	
	PROFILE_ADM10_LINE_UpdateOTU2EFECPerfValues(Profile, Idx);
	PROFILE_ADM10_LINE_UpdateOTU2FECPerfValues(Profile, Idx);
	PROFILE_ADM10_LINE_UpdateOTU2PerfValues(Profile, Idx);
	PROFILE_ADM10_LINE_UpdateODU2PerfValues(Profile, Idx);
	for (i = 0 ; i < 4; i++)
		PROFILE_ADM10_LINE_UpdateODU1PerfValues(Profile, Idx, i);
	for (i = 0 ; i < 8; i++)
		PROFILE_ADM10_LINE_UpdateODU0PerfValues(Profile, Idx, i);
}

static void PROFILE_ADM10_LINE_UpdateAlarmLedValue(PROFILE_T *Profile, uint32_t Idx)
{
	uint32_t LedColor, i;
	uint8_t Color, ParamColor, ParamState;
	uint8_t State;
	
	if (PROFILE_ADM10_LINE_GetState(Profile, Idx, &State))
		return;
	
	if (State == PROFILE_STATE_IS)
	{
		Color = PROFILE_COLOR_NORMAL;
		
		PROFILE_GetColor(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnSFPStateIdx[Idx], &ParamColor);
		PROFILE_GetState(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnSFPStateIdx[Idx], &ParamState);
		if ((ParamState == PROFILE_STATE_IS) && (Color < ParamColor))
			Color = ParamColor;
		
		PROFILE_GetColor(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnSFPTempIdx[Idx], &ParamColor);
		PROFILE_GetState(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnSFPTempIdx[Idx], &ParamState);
		if ((ParamState == PROFILE_STATE_IS) && (Color < ParamColor))
			Color = ParamColor;
		
		PROFILE_GetColor(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnSFPRxPwrIdx[Idx], &ParamColor);
		PROFILE_GetState(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnSFPRxPwrIdx[Idx], &ParamState);
		if ((ParamState == PROFILE_STATE_IS) && (Color < ParamColor))
			Color = ParamColor;
		
		PROFILE_GetColor(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnSFPTxPwrIdx[Idx], &ParamColor);
		PROFILE_GetState(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnSFPTxPwrIdx[Idx], &ParamState);
		if ((ParamState == PROFILE_STATE_IS) && (Color < ParamColor))
			Color = ParamColor;
		
		PROFILE_GetColor(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnOTU2AlarmsIdx[Idx], &ParamColor);
		PROFILE_GetState(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnOTU2AlarmsIdx[Idx], &ParamState);
		if ((ParamState == PROFILE_STATE_IS) && (Color < ParamColor))
			Color = ParamColor;
		
		PROFILE_GetColor(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnODU2AlarmsIdx[Idx], &ParamColor);
		PROFILE_GetState(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnODU2AlarmsIdx[Idx], &ParamState);
		if ((ParamState == PROFILE_STATE_IS) && (Color < ParamColor))
			Color = ParamColor;
		
		PROFILE_GetColor(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnOPU2AlarmsIdx[Idx], &ParamColor);
		PROFILE_GetState(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnOPU2AlarmsIdx[Idx], &ParamState);
		if ((ParamState == PROFILE_STATE_IS) && (Color < ParamColor))
			Color = ParamColor;
		
		for (i = 0; i < 4; i++)
		{
			PROFILE_GetColor(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnODU1AlarmsIdx[Idx][i], &ParamColor);
			PROFILE_GetState(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnODU1AlarmsIdx[Idx][i], &ParamState);
			if ((ParamState == PROFILE_STATE_IS) && (Color < ParamColor))
				Color = ParamColor;
		}
		
		for (i = 0; i < 4; i++)
		{
			PROFILE_GetColor(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnOPU1AlarmsIdx[Idx][i], &ParamColor);
			PROFILE_GetState(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnOPU1AlarmsIdx[Idx][i], &ParamState);
			if ((ParamState == PROFILE_STATE_IS) && (Color < ParamColor))
				Color = ParamColor;
		}
		
		for (i = 0; i < 8; i++)
		{
			PROFILE_GetColor(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnODU0AlarmsIdx[Idx][i], &ParamColor);
			PROFILE_GetState(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnODU0AlarmsIdx[Idx][i], &ParamState);
			if ((ParamState == PROFILE_STATE_IS) && (Color < ParamColor))
				Color = ParamColor;
		}
		
		for (i = 0; i < 8; i++)
		{
			PROFILE_GetColor(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnOPU0AlarmsIdx[Idx][i], &ParamColor);
			PROFILE_GetState(Profile, PROFILE_TABLE_2, ProfileADM10DynamicLnOPU0AlarmsIdx[Idx][i], &ParamState);
			if ((ParamState == PROFILE_STATE_IS) && (Color < ParamColor))
				Color = ParamColor;
		}
		
		if (Color == 7)
		{
			BSP_SFP_PIN_SetAlarmLed(BSP_SFP_LINE_IDX(Idx), BSP_SFP_PIN_LED_RED);
			LedColor = 2;
			PROFILE_SetValue(Profile, PROFILE_TABLE_5, ProfileADM10LedLnAlarmIdx[Idx], &LedColor);
		}
		else if ((Color > 3) && (Color < 7))
		{
			BSP_SFP_PIN_SetAlarmLed(BSP_SFP_LINE_IDX(Idx), BSP_SFP_PIN_LED_YELLOW);
			LedColor = 3;
			PROFILE_SetValue(Profile, PROFILE_TABLE_5, ProfileADM10LedLnAlarmIdx[Idx], &LedColor);
		}
		else if (Color == 3)
		{
			BSP_SFP_PIN_SetAlarmLed(BSP_SFP_LINE_IDX(Idx), BSP_SFP_PIN_LED_GREEN);
			LedColor = 1;
			PROFILE_SetValue(Profile, PROFILE_TABLE_5, ProfileADM10LedLnAlarmIdx[Idx], &LedColor);
		}
		else
		{
			BSP_LED_Set(BSP_LED_TYPE_ALARM, BSP_LED_COLOR_NO);
			LedColor = 0;
			PROFILE_SetValue(Profile, PROFILE_TABLE_5, ProfileADM10LedLnAlarmIdx[Idx], &LedColor);
		}
	}
	else
	{
		BSP_SFP_PIN_SetAlarmLed(BSP_SFP_LINE_IDX(Idx), BSP_SFP_PIN_LED_OFF);
		LedColor = 0;
		PROFILE_SetValue(Profile, PROFILE_TABLE_5, ProfileADM10LedLnAlarmIdx[Idx], &LedColor);
	}
}

static void PROFILE_ADM10_LINE_UpdateEnableTxLedValue(PROFILE_T *Profile, uint32_t Idx)
{
	uint32_t EnableTx, LedColor;
	
	if (PROFILE_GetValue(Profile, PROFILE_TABLE_3, ProfileADM10ConfigLnSFPEnableTxIdx[Idx], &EnableTx))
		return;
	
	if (EnableTx)
	{
		BSP_SFP_PIN_SetTxEnableLed(BSP_SFP_LINE_IDX(Idx), BSP_SFP_PIN_LED_GREEN);
		LedColor = 1;
		PROFILE_SetValue(Profile, PROFILE_TABLE_5, ProfileADM10LedLnEnableTxIdx[Idx], &LedColor);
	}
	else
	{
		BSP_SFP_PIN_SetTxEnableLed(BSP_SFP_LINE_IDX(Idx), BSP_SFP_PIN_LED_OFF);
		LedColor = 0;
		PROFILE_SetValue(Profile, PROFILE_TABLE_5, ProfileADM10LedLnEnableTxIdx[Idx], &LedColor);
	}
}

static void PROFILE_ADM10_LINE_UpdateLeds(PROFILE_T *Profile, uint32_t Idx)
{
	PROFILE_ADM10_LINE_UpdateAlarmLedValue(Profile, Idx);
	PROFILE_ADM10_LINE_UpdateEnableTxLedValue(Profile, Idx);
}

void PROFILE_ADM10_LINE_UpdateValues(PROFILE_T *Profile)
{
	uint32_t i;
	
	for (i = 0; i < PROFILE_ADM10_LINE_PORTS; i++)
	{
		PROFILE_ADM10_LINE_UpdateInfoAndStaticValues(Profile, i);
		PROFILE_ADM10_LINE_UpdateDynamicValues(Profile, i);
		PROFILE_ADM10_LINE_UpdatePerfValues(Profile, i);
		PROFILE_ADM10_LINE_UpdateLeds(Profile, i);
	}
}
